const nameList = (v, key) => Array.isArray(v) ? v.map((e) => (e && typeof e === 'object' ? String(e[key] ?? '') : '')).filter(Boolean) : [];
export function githubIssueConnector(execute, owner, repo) {
    const repository = `${owner}/${repo}`;
    return {
        service: 'github',
        cursorFile: `${owner}-${repo}.json`,
        async fetchSince({ cursor, limit }) {
            const observations = [];
            let truncated = false;
            for (let page = 1; !truncated; page++) {
                const params = { owner, repo, state: 'all', sort: 'updated', direction: 'desc', per_page: 100, page };
                if (cursor)
                    params.since = cursor; // empty cursor = full bootstrap
                const res = await execute.request('GET /repos/{owner}/{repo}/issues', params);
                if (res.status >= 400)
                    throw new Error(`github connector: list issues failed (HTTP ${res.status})`);
                const nodes = Array.isArray(res.data) ? res.data : [];
                for (const n of nodes) {
                    if (n.pull_request != null)
                        continue; // the issues endpoint also returns PRs — drop them
                    const number = Number(n.number);
                    const observed = { number, repository };
                    if (n.title != null)
                        observed.title = String(n.title);
                    if (n.body != null)
                        observed.body = String(n.body);
                    if (n.state != null)
                        observed.state = String(n.state);
                    const assignees = nameList(n.assignees, 'login');
                    if (assignees.length)
                        observed.assignees = assignees;
                    const labels = nameList(n.labels, 'name');
                    if (labels.length)
                        observed.labels = labels;
                    observations.push({
                        subject: { type: 'issue', id: `${repository}#issue:${number}` },
                        observed,
                        occurredAt: String(n.updated_at ?? n.created_at ?? ''),
                        external: { provider: 'github', id: String(number), ...(n.html_url ? { url: String(n.html_url) } : {}) },
                    });
                    if (observations.length >= limit) {
                        truncated = true;
                        break;
                    } // safety cap → runner holds the cursor
                }
                if (nodes.length < 100)
                    break; // last page
            }
            return { observations, truncated };
        },
    };
}
